const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const since = sevenDaysAgo.toISOString();
const windowLabel = `${sevenDaysAgo.toISOString().slice(0,10)} → ${now.toISOString().slice(0,10)}`;

return [{ json: { since, windowLabel } }];

// Items arrive from three parallel branches. We collect by source name.
const items = $input.all();

// Each branch produces an array at .json (raw GitHub API response is an array)
// n8n splits arrays into individual items, so we reassemble by node.
// Use $('NodeName').all() to read each branch.

const since = $('Compute Date Window').first().json.since;
const windowLabel = $('Compute Date Window').first().json.windowLabel;

const allCommits = $('Fetch Commits').all().map(i => i.json);
const allIssues = $('Fetch Closed Issues').all().map(i => i.json)
  .filter(i => !i.pull_request); // exclude PRs that appear in issues endpoint
const allPRs = $('Fetch Merged PRs').all().map(i => i.json)
  .filter(i => i.merged_at && new Date(i.merged_at) >= new Date(since));

const repo = process.env.GITHUB_REPO;
const language = (process.env.SUMMARY_LANGUAGE || 'EN').toUpperCase();

return [{
  json: {
    repo,
    language,
    windowLabel,
    since,
    commitCount: allCommits.length,
    issueCount: allIssues.length,
    prCount: allPRs.length,
    commits: allCommits.slice(0, 30).map(c => ({
      sha: c.sha?.slice(0, 7),
      message: c.commit?.message?.split('\n')[0],
      author: c.commit?.author?.name,
      date: c.commit?.author?.date?.slice(0, 10)
    })),
    issues: allIssues.slice(0, 20).map(i => ({
      number: i.number,
      title: i.title,
      closedBy: i.closed_by?.login,
      closedAt: i.closed_at?.slice(0, 10)
    })),
    prs: allPRs.slice(0, 20).map(p => ({
      number: p.number,
      title: p.title,
      mergedBy: p.merged_by?.login,
      mergedAt: p.merged_at?.slice(0, 10)
    }))
  }
}];

const d = $json;
const isEN = d.language !== 'FR';

const systemEN = `You are a developer newsletter writer. Summarize a week of GitHub repository activity into an engaging, human-readable narrative for the engineering team. Be specific—mention feature names, bug fixes, and contributor names. Write in a friendly, professional tone. Use bullet points for the activity sections. Keep the total under 400 words.`;

const systemFR = `Tu es un rédacteur de newsletter pour développeurs. Résume une semaine d'activité sur un dépôt GitHub en un récit engageant et lisible par l'équipe d'ingénierie. Sois précis—mentionne les noms de fonctionnalités, les corrections de bugs et les noms des contributeurs. Adopte un ton amical et professionnel. Utilise des puces pour les sections d'activité. Reste en dessous de 400 mots.`;

const userEN = `Here is the GitHub activity for ${d.repo} during ${d.windowLabel}:

**Commits (${d.commitCount} total, showing up to 30):**
${d.commits.map(c => `- [${c.sha}] ${c.message} (${c.author}, ${c.date})`).join('\n') || 'No commits'}

**Closed Issues (${d.issueCount} total, showing up to 20):**
${d.issues.map(i => `- #${i.number}: ${i.title} (closed by ${i.closedBy}, ${i.closedAt})`).join('\n') || 'No closed issues'}

**Merged PRs (${d.prCount} total, showing up to 20):**
${d.prs.map(p => `- #${p.number}: ${p.title} (merged by ${p.mergedBy}, ${p.mergedAt})`).join('\n') || 'No merged PRs'}

Write the weekly summary now.`;

const userFR = `Voici l'activité GitHub pour ${d.repo} du ${d.windowLabel} :\n\n**Commits (${d.commitCount} au total, jusqu'à 30 affichés) :**\n${d.commits.map(c => `- [${c.sha}] ${c.message} (${c.author}, ${c.date})`).join('\n') || 'Aucun commit'}\n\n**Issues fermées (${d.issueCount} au total, jusqu'à 20 affichées) :**\n${d.issues.map(i => `- #${i.number} : ${i.title} (fermée par ${i.closedBy}, ${i.closedAt})`).join('\n') || 'Aucune issue fermée'}\n\n**PRs fusionnées (${d.prCount} au total, jusqu'à 20 affichées) :**\n${d.prs.map(p => `- #${p.number} : ${p.title} (fusionnée par ${p.mergedBy}, ${p.mergedAt})`).join('\n') || 'Aucune PR fusionnée'}\n\nRédige le résumé hebdomadaire maintenant.`;

return [{
  json: {
    ...d,
    claudePayload: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 1024,
      system: isEN ? systemEN : systemFR,
      messages: [{ role: 'user', content: isEN ? userEN : userFR }]
    }
  }
}];

const claudeResponse = $json;
const summaryText = claudeResponse.content?.[0]?.text || '(no summary generated)';

const prev = $('Build Claude Prompt').first().json;

const header = prev.language === 'FR'
  ? `📊 *Résumé hebdomadaire — ${prev.repo}*\n_${prev.windowLabel}_\n\n`
  : `📊 *Weekly Dev Summary — ${prev.repo}*\n_${prev.windowLabel}_\n\n`;

return [{
  json: {
    repo: prev.repo,
    windowLabel: prev.windowLabel,
    language: prev.language,
    discordMessage: header + summaryText
  }
}];
